    *eclipse = 0;
    *behind_m = 0.0;
    *miss_m = INFINITY;
    return ADCS_E_RANGE;
}

// 3. Normalize Sun direction
if (adcs_vec3_normalize(sun_direction, ADCS_EPS_NORM, &sun_dir_norm) != ADCS_OK) {
    // Degenerate vector treated as invalid/range per requirement
